uint32_t modexp(uint32_t base, uint32_t exponent, uint32_t modulus) {
    uint32_t running_square = (modulus > 0) ? (base % modulus) : base;

    // Defect: accumulator is now heap-allocated instead of a fixed-size
    // scalar/local array, violating the HLS "no dynamic allocation"
    // constraint (FR3). This is functionally transparent but forbidden
    // for HLS synthesis and for the static-scan / compile constraints.
    uint32_t *accumulator_ptr = new uint32_t;
    *accumulator_ptr = (modulus > 1) ? (1u % modulus) : 0u;

    uint32_t local_iterations = 0;

    for (uint32_t i = 0; i < 32u; ++i) {
        uint32_t bit = (exponent >> i) & 1u;

        uint32_t multiply_candidate = modexp_multiply_hook(*accumulator_ptr, running_square, modulus);

        uint32_t mask = static_cast<uint32_t>(-(int32_t)bit);
        *accumulator_ptr = (multiply_candidate & mask) | (*accumulator_ptr & ~mask);

        running_square = modexp_multiply_hook(running_square, running_square, modulus);

        local_iterations = local_iterations + 1u;
    }

    g_modexp_last_iterations = local_iterations;

    uint32_t result = *accumulator_ptr;
    delete accumulator_ptr;

    return result;
}

